div.script:
(function () {
    function initializeSignatureWidgets() {
        var widgets = document.querySelectorAll('.o_test_page_signature_widget');
        widgets.forEach(function (widget) {
            if (widget.dataset.signatureInitialized === '1') {
                return;
            }
            widget.dataset.signatureInitialized = '1';

            var fullNameInput = document.getElementById(widget.dataset.fullNameInputId);
            var form = widget.closest('form');
            var hiddenSignatureInput = widget.querySelector('input[name="signature"]');
            var hiddenSignatureNameInput = widget.querySelector('input[name="signature_name"]');
            var typedInput = widget.querySelector('.o_signature_typed_name');
            var canvas = widget.querySelector('.o_signature_canvas');
            var previewImage = widget.querySelector('.o_signature_preview_image');
            var previewPlaceholder = widget.querySelector('.o_signature_preview_placeholder');
            var errorBox = widget.querySelector('.o_signature_error');
            var modeButtons = widget.querySelectorAll('.o_signature_mode_btn');
            var typeMode = widget.querySelector('.o_signature_mode_type');
            var drawMode = widget.querySelector('.o_signature_mode_draw');
            var clearDrawButton = widget.querySelector('.o_signature_clear_draw');
            var useTypedButton = widget.querySelector('.o_signature_apply_typed');
            var useDrawButton = widget.querySelector('.o_signature_apply_draw');
            var signaturePad = null;

            function showError(message) {
                errorBox.textContent = message;
                errorBox.classList.remove('d-none');
            }

            function clearError() {
                errorBox.textContent = '';
                errorBox.classList.add('d-none');
            }

            function syncTypedName(force) {
                if (!fullNameInput) {
                    return;
                }
                if (force || !typedInput.value || typedInput.dataset.userEdited !== '1') {
                    typedInput.value = fullNameInput.value || '';
                }
            }

            function setPreview(signatureDataUrl, signatureName) {
                hiddenSignatureInput.value = signatureDataUrl;
                hiddenSignatureNameInput.value = signatureName || (fullNameInput && fullNameInput.value) || '';
                previewImage.src = signatureDataUrl;
                previewImage.classList.remove('d-none');
                previewPlaceholder.classList.add('d-none');
                clearError();
            }

            function setMode(mode) {
                modeButtons.forEach(function (button) {
                    var isActive = button.dataset.mode === mode;
                    button.classList.toggle('active', isActive);
                });
                typeMode.classList.toggle('d-none', mode !== 'type');
                drawMode.classList.toggle('d-none', mode !== 'draw');
                if (mode === 'draw') {
                    resizeCanvas();
                }
            }

            function resizeCanvas() {
                if (!canvas || !window.SignaturePad) {
                    return;
                }
                var ratio = Math.max(window.devicePixelRatio || 1, 1);
                var width = canvas.offsetWidth;
                var height = canvas.offsetHeight;
                canvas.width = width * ratio;
                canvas.height = height * ratio;
                canvas.getContext('2d').scale(ratio, ratio);
                if (!signaturePad) {
                    signaturePad = new window.SignaturePad(canvas, {
                        penColor: '#1a4a54',
                        minWidth: 1.5,
                        maxWidth: 2.2,
                        backgroundColor: 'rgba(255,255,255,0)',
                    });
                } else {
                    signaturePad.clear();
                }
            }

            function createTypedSignature(name) {
                var text = (name || '').trim();
                if (!text) {
                    showError('Please type a name for the signature first.');
                    return;
                }

                var typedCanvas = document.createElement('canvas');
                typedCanvas.width = 780;
                typedCanvas.height = 220;
                var ctx = typedCanvas.getContext('2d');
                var fontSize = 76;

                ctx.clearRect(0, 0, typedCanvas.width, typedCanvas.height);
                ctx.fillStyle = '#1a4a54';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';

                while (fontSize > 34) {
                    ctx.font = 'italic ' + fontSize + 'px cursive';
                    if (ctx.measureText(text).width <= 680) {
                        break;
                    }
                    fontSize -= 4;
                }

                ctx.font = 'italic ' + fontSize + 'px cursive';
                ctx.fillText(text, typedCanvas.width / 2, typedCanvas.height / 2);

                setPreview(typedCanvas.toDataURL('image/png'), text);
            }

            modeButtons.forEach(function (button) {
                button.addEventListener('click', function () {
                    setMode(button.dataset.mode);
                });
            });

            typedInput.addEventListener('input', function () {
                typedInput.dataset.userEdited = '1';
            });

            if (fullNameInput) {
                syncTypedName(true);
                fullNameInput.addEventListener('input', function () {
                    syncTypedName(false);
                });
            }

            useTypedButton.addEventListener('click', function () {
                createTypedSignature(typedInput.value || (fullNameInput && fullNameInput.value) || '');
            });

            clearDrawButton.addEventListener('click', function () {
                if (signaturePad) {
                    signaturePad.clear();
                }
                clearError();
            });

            useDrawButton.addEventListener('click', function () {
                if (!signaturePad || signaturePad.isEmpty()) {
                    showError('Please draw your signature before using it.');
                    return;
                }
                setPreview(
                    signaturePad.toDataURL('image/png'),
                    typedInput.value || (fullNameInput && fullNameInput.value) || ''
                );
            });

            if (form) {
                form.addEventListener('submit', function (ev) {
                    if (!hiddenSignatureInput.value) {
                        ev.preventDefault();
                        showError('Please choose a typed or drawn signature before submitting.');
                        widget.scrollIntoView({
                            behavior: 'smooth',
                            block: 'center',
                        });
                    }
                });
            }

            if (!window.SignaturePad) {
                widget.querySelector('[data-mode="draw"]').disabled = true;
                widget.querySelector('[data-mode="draw"]').title = 'Draw mode is currently unavailable.';
            } else {
                resizeCanvas();
                window.addEventListener('resize', function () {
                    if (!drawMode.classList.contains('d-none')) {
                        resizeCanvas();
                    }
                });
            }

            setMode('type');
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initializeSignatureWidgets);
    } else {
        initializeSignatureWidgets();
    }
})();
